SourceCode.Declaration:
/// <summary>
/// Count control center: Post now - posts the selected store journal at once instead of tonight.
/// </summary>
class HSMobileOpsCountStoreJournalPost
{
}

Method.Source:
public static void main(Args _args)
{
    HSMobileOpsCountStoreJournal storeJournal = _args ? _args.record() : null;

    if (!storeJournal || !storeJournal.RecId)
    {
        throw error('Select a store first.');
    }
    if (HSMobileOpsCountStoreJournalEngine::post(storeJournal.RecId, true))
    {
        info(strFmt('Store journal %1 of %2 is posted.', storeJournal.JournalId, storeJournal.InventLocationId));
    }
    HSMobileOpsCountRefresh::researchCaller(_args);
}
